1	import {
2	  EXTERNAL_TASK_STATUS_LABELS,
3	  type ExternalTask,
4	  type ExternalTaskMeta,
5	} from '../../src/types/task';
6	import type { Conversation, ReminderItem } from '../../src/types/conversation';
7	import type { AgentOrigin } from '../../src/types/agentOrigin';
8	import { root } from '../config';
9	import { resolveAgentOrigin } from '../lib/agentOrigin';
10	import { saveConversation, saveFailureReason } from './conversationStore';
11	import { subscribe, type WorkstationEvent } from './eventBus';
12	import { checkConversationWrite } from './identityGuard';
13	import { sendSystemPush } from './pushNotifier';
14	import {
15	  REMINDERS_ID,
16	  REMINDERS_SLUG,
17	  buildReminderItem,
18	  listAllReminders,
19	  loadOrInitRemindersConversation,
20	} from './reminderStore';
21	import { findTask, listTasks } from './taskStore';
22	
23	/**
24	 * Failure alerting for Operations › Daemons & jobs — "a job never fails
25	 * silently again, without having to open the Operations page".
26	 *
27	 * When a supervised launchd task (see taskManager.checkTaskHealth) goes into a
28	 * degraded state (`health.healthy === false`: failed run, late run, daemon
29	 * down/not loaded), ONE alert is raised:
30	 *   1. a `high`-priority reminder in the evergreen `_reminders/rappels`
31	 *      conversation (visible at the top of the dashboard and in the bell);
32	 *   2. a Web Push (inert without VAPID keys), sent ONLY when that reminder is
33	 *      newly created.
34	 *
35	 * Dedup — at most ONE PENDING alert reminder per task:
36	 *   - alert reminders carry a parseable id `reminder-taskalert-<taskId>-<t36>-<rand6>`;
37	 *   - while one is pending for a task, no other is created (checked on a FRESH
38	 *     read of the reminders conversation, inside the write retry loop);
39	 *   - in memory, a task already alerted for its current degraded "episode" is
40	 *     not re-alerted even if the user marks the reminder done while the job is
41	 *     still failing; the episode ends when the task is observed healthy again.
42	 *     A recovery never auto-closes the reminder (the user must see it).
43	 *
44	 * Freshness: only health computed AFTER this alerter started is trusted
45	 * (`health.lastCheckedAt >= startedAt`) — a persisted health from before a
46	 * restart may be stale. So at boot nothing fires until the first health-loop
47	 * tick; then a task that failed while the server was down and has no pending
48	 * alert IS alerted, while one that already has a pending alert is not.
49	 *
50	 * Triggers: `task-healthcheck` bus events (immediate), plus a periodic sweep
51	 * (default 60 s) — the health loop does NOT publish on the very first check of
52	 * a task (unknown → unhealthy), and its scheduled-job event payload reports
53	 * `ok: !late` (a failed-but-on-time run publishes ok:true), so the alerter
54	 * never trusts the event payload: it re-reads the task from the store.
55	 * `task-status` is not used — a failed launchctl action is followed by a
56	 * health check, which is what decides.
57	 *
58	 * All writes are serialized through one in-process queue (several tasks can
59	 * transition in the same tick).
60	 */
61	
62	/* -------------------------------------------------------------------------- */
63	/*  Constants                                                                 */
64	/* -------------------------------------------------------------------------- */
65	
66	/** Dashboard location of the Daemons & jobs panel (Operations = /pilotage,
67	 *  DevOps tab, section 00). The front syncs `?tab=` on navigation. */
68	export const TASK_ALERT_HREF = '/pilotage?tab=devops';
69	
70	const ALERT_ID_PREFIX = 'reminder-taskalert-';
71	const ALERT_ID_RE = /^reminder-taskalert-(.+)-([a-z0-9]+)-([a-z0-9]{6})$/;
72	const WRITE_MAX_ATTEMPTS = 3;
73	const DEFAULT_SWEEP_MS = 60_000;
74	
75	/* -------------------------------------------------------------------------- */
76	/*  Pure helpers                                                              */
77	/* -------------------------------------------------------------------------- */
78	
79	export function newAlertItemId(taskId: string): string {
80	  const rand = Math.random().toString(36).slice(2, 8).padEnd(6, '0');
81	  return `${ALERT_ID_PREFIX}${taskId}-${Date.now().toString(36)}-${rand}`;
82	}
83	
84	/** Task id carried by an alert reminder id, or null for any other reminder. */
85	export function taskIdFromAlertItemId(itemId: string): string | null {
86	  const m = ALERT_ID_RE.exec(itemId);
87	  return m ? m[1] : null;
88	}
89	
90	/** The single "degraded" predicate shared by the alerter and the bell. */
91	export function isTaskDegraded(task: Pick<ExternalTask, 'health'>): boolean {
92	  return task.health.healthy === false;
93	}
94	
95	function healthMessage(task: Pick<ExternalTask, 'health' | 'status'>): string {
96	  return task.health.message || EXTERNAL_TASK_STATUS_LABELS[task.status];
97	}
98	
99	export function alertReminderText(task: Pick<ExternalTask, 'title' | 'health' | 'status'>): string {
100	  return `Job en échec : ${task.title} — ${healthMessage(task)} (Operations › Daemons & jobs)`;
101	}
102	
103	/**
104	 * Origin of a reminder written by the server itself. There is no 'system'
105	 * source in the Origin enum: `source: 'http'` is what the other server-side
106	 * background writers already use (boussoleBridge poller, htmlshare ingest) —
107	 * the record is written by the API process. The env is deliberately EMPTY so
108	 * a dev server launched from inside a Claude/Codex session never attributes
109	 * the alert to that session: runtime 'unknown', capturedBy 'none'.
110	 */
111	function systemOrigin(): AgentOrigin {
112	  return resolveAgentOrigin({ env: {}, cwd: root(), source: 'http' });
113	}
114	
115	function pendingAlertTaskIds(conversation: Conversation): Set<string> {
116	  const ids = new Set<string>();
117	  for (const item of conversation.items) {
118	    if (item.kind !== 'reminder' || item.status !== 'pending') continue;
119	    const taskId = taskIdFromAlertItemId(item.id);
120	    if (taskId) ids.add(taskId);
121	  }
122	  return ids;
123	}
124	
125	/** Whether a reminder id is an automatic job-failure alert (see newAlertItemId). */
126	export function isTaskAlertReminderId(itemId: string): boolean {
127	  return taskIdFromAlertItemId(itemId) !== null;
128	}
129	
130	/**
131	 * taskId → id of its MOST RECENT alert reminder, pending OR done — the bell
132	 * episode identity. Keyed on the reminder whatever its status, so marking it
133	 * done while the job still fails keeps the same bell id (no second desktop
134	 * notification for an acknowledged failure); a new failure episode creates a
135	 * new reminder, hence a new id.
136	 */
137	async function latestAlertsByTask(): Promise<Map<string, string>> {
138	  const map = new Map<string, string>();
139	  // Reminders are appended in creation order: the last one per task wins.
140	  for (const item of await listAllReminders()) {
141	    const taskId = taskIdFromAlertItemId(item.id);
142	    if (taskId) map.set(taskId, item.id);
143	  }
144	  return map;
145	}
146	
147	/* -------------------------------------------------------------------------- */
148	/*  Reminder write                                                            */
149	/* -------------------------------------------------------------------------- */
150	
151	/**
152	 * Append one high-priority alert reminder for `task`, unless one is already
153	 * pending for it. Bounded optimistic-lock retry, same idiom as the
154	 * `remind_add` MCP tool (fresh read → append → save → verify the item
155	 * survived → retry on conflict). Returns the created item, or null when a
156	 * pending alert already existed.
157	 */
158	async function createAlertReminder(task: ExternalTask): Promise<ReminderItem | null> {
159	  let lastReason: string | undefined;
160	  for (let attempt = 1; attempt <= WRITE_MAX_ATTEMPTS; attempt++) {
161	    const conversation = await loadOrInitRemindersConversation('http');
162	    if (pendingAlertTaskIds(conversation).has(task.id)) return null;
163	
164	    const built = buildReminderItem(
165	      {
166	        text: alertReminderText(task),
167	        context:
168	          `Alerte automatique de la workstation : le job launchd ${task.launchdLabel} ` +
169	          `(projet ${task.project.name}) est passé en échec. Détails et logs : ` +
170	          `Operations › Daemons & jobs (${TASK_ALERT_HREF}). Marquer ce rappel fait une fois traité ; ` +
171	          'une nouvelle alerte ne sera levée que lors d’un prochain échec.',
172	      },
173	      systemOrigin(),
174	    );
175	    const item: ReminderItem = { ...built, id: newAlertItemId(task.id), priority: 'high' };
176	
177	    const guard = checkConversationWrite({ items: [item] }, 'claude');
178	    if (!guard.allowed) throw new Error(guard.reason);
179	
180	    const next: Conversation = { ...conversation, items: [...conversation.items, item] };
181	    const result = await saveConversation(REMINDERS_SLUG, REMINDERS_ID, next);
182	    if (result.ok) {
183	      if (result.conversation.items.some((it) => it.id === item.id)) return item;
184	      lastReason = 'item non retrouvé après écriture';
185	      continue;
186	    }
187	    if ('conflict' in result && result.conflict) {
188	      lastReason = saveFailureReason(result);
189	      continue;
190	    }
191	    throw new Error(`store a rejeté l’écriture: ${saveFailureReason(result)}`);
192	  }
193	  throw new Error(
194	    `taskAlerter: échec après ${WRITE_MAX_ATTEMPTS} tentatives — ${lastReason ?? 'raison inconnue'}`,
195	  );
196	}
197	
198	/* -------------------------------------------------------------------------- */
199	/*  Alerter state + evaluation                                                */
200	/* -------------------------------------------------------------------------- */
201	
202	let startedAtMs = 0;
203	let active = false;
204	/** Task ids already alerted (or found with a pending alert) for their current
205	 *  degraded episode. Cleared per task when it is observed healthy again. */
206	const alertedEpisodes = new Set<string>();
207	let queue: Promise<void> = Promise.resolve();
208	
209	function enqueue(fn: () => Promise<void>): Promise<void> {
210	  queue = queue.then(fn).catch((err) => {
211	    // eslint-disable-next-line no-console
212	    console.warn('[taskAlerter] évaluation échouée (non-fatal):', String(err));
213	  });
214	  return queue;
215	}
216	
217	function isFresh(snapshot: Pick<ExternalTask, 'health'>): boolean {
218	  const checked = snapshot.health.lastCheckedAt ? Date.parse(snapshot.health.lastCheckedAt) : NaN;
219	  return !Number.isNaN(checked) && checked >= startedAtMs;
220	}
221	
222	/**
223	 * Decide from a health snapshot (a task meta from the sweep's single
224	 * `listTasks()` read, or the task an event just re-read) and load the FULL
225	 * task only when an alert may actually be raised — a healthy sweep costs one
226	 * directory read, not one lookup per task.
227	 */
228	async function evaluateSnapshot(
229	  snapshot: Pick<ExternalTask, 'id' | 'health'>,
230	  full?: ExternalTask,
231	): Promise<void> {
232	  if (!active || !isFresh(snapshot)) return;
233	
234	  if (!isTaskDegraded(snapshot)) {
235	    alertedEpisodes.delete(snapshot.id);
236	    return;
237	  }
238	  if (alertedEpisodes.has(snapshot.id)) return;
239	
240	  const task = full ?? (await findTask(snapshot.id));
241	  if (!task || !isFresh(task) || !isTaskDegraded(task)) return;
242	
243	  const created = await createAlertReminder(task);
244	  alertedEpisodes.add(task.id);
245	  if (!created) return;
246	
247	  try {
248	    await sendSystemPush({
249	      title: `Job en échec : ${task.title}`,
250	      body: healthMessage(task),
251	      url: TASK_ALERT_HREF,
252	    });
253	  } catch (err) {
254	    // eslint-disable-next-line no-console
255	    console.warn('[taskAlerter] push échoué (non-fatal):', String(err));
256	  }
257	}
258	
259	async function evaluateTask(id: string): Promise<void> {
260	  if (!active) return;
261	  const task = await findTask(id);
262	  if (task) await evaluateSnapshot(task, task);
263	}
264	
265	/** Evaluate one task (serialized). Exported for tests. */
266	export function evaluateTaskAlert(id: string): Promise<void> {
267	  return enqueue(() => evaluateTask(id));
268	}
269	
270	/** Evaluate every registered task (serialized). Exported for tests; also the
271	 *  periodic sweep body. */
272	export function runTaskAlertSweep(): Promise<void> {
273	  return enqueue(async () => {
274	    const metas = await listTasks();
275	    for (const m of metas) await evaluateSnapshot(m);
276	  });
277	}
278	
279	function onBusEvent(event: WorkstationEvent): void {
280	  if (event.type !== 'task-healthcheck' || !event.id) return;
281	  void evaluateTaskAlert(event.id);
282	}
283	
284	/**
285	 * Boot entry point (server/index.ts). Subscribes to the bus and starts the
286	 * periodic sweep (`sweepIntervalMs: 0` disables the timer — tests drive
287	 * `runTaskAlertSweep` directly). Returns a stop function. Calling start again
288	 * resets the in-memory state (fresh "boot").
289	 */
290	export function startTaskAlerter(opts: { sweepIntervalMs?: number } = {}): () => void {
291	  startedAtMs = Date.now();
292	  active = true;
293	  alertedEpisodes.clear();
294	  const unsubscribe = subscribe(onBusEvent);
295	  const sweepMs = opts.sweepIntervalMs ?? DEFAULT_SWEEP_MS;
296	  const timer = sweepMs > 0 ? setInterval(() => void runTaskAlertSweep(), sweepMs) : null;
297	  timer?.unref?.();
298	  return () => {
299	    active = false;
300	    unsubscribe();
301	    if (timer) clearInterval(timer);
302	  };
303	}
304	
305	/** Wait for every queued evaluation to settle — for tests. */
306	export function taskAlerterIdle(): Promise<void> {
307	  return queue;
308	}
309	
310	/* -------------------------------------------------------------------------- */
311	/*  Bell (GET /api/notifications)                                             */
312	/* -------------------------------------------------------------------------- */
313	
314	export interface TaskAlertNotification {
315	  id: string;
316	  title: string;
317	  context: string;
318	  project: { slug: string; name: string };
319	  href: string;
320	  kind: 'task-alert';
321	  updatedAt: string;
322	}
323	
324	/**
325	 * One bell entry per task CURRENTLY degraded (persisted health) that has an
326	 * alert reminder: the reminder is the acknowledgment trail, this entry is the
327	 * live state (still shown after the reminder is marked done, until the job is
328	 * healthy again). Its id embeds the task's most recent alert reminder id,
329	 * pending or done, so it is stable for the whole failure episode: marking the
330	 * reminder done never re-notifies, and a NEW episode (new reminder) does.
331	 * A degraded task without any alert reminder yet (the ≤ 60 s before the
332	 * alerter's sweep writes it) is not listed, so a failure never surfaces under
333	 * two successive ids. The alert reminders themselves are left out of the
334	 * bell's reminder items (see `isTaskAlertReminderId` in routes/insights.ts):
335	 * one failure, one bell entry.
336	 */
337	export async function listTaskAlertNotifications(): Promise<TaskAlertNotification[]> {
338	  const metas: ExternalTaskMeta[] = await listTasks();
339	  const degraded = metas.filter(isTaskDegraded);
340	  if (degraded.length === 0) return [];
341	  const alerts = await latestAlertsByTask().catch(() => new Map<string, string>());
342	  return degraded.flatMap((m) => {
343	    const reminderId = alerts.get(m.id);
344	    if (!reminderId) return [];
345	    return [
346	      {
347	        id: `task-alert:${m.project.slug}:${m.id}:${reminderId}`,
348	        title: `Job en échec : ${m.title}`,
349	        context: healthMessage(m),
350	        project: { slug: m.project.slug, name: m.project.name },
351	        href: TASK_ALERT_HREF,
352	        kind: 'task-alert' as const,
353	        updatedAt: m.health.lastCheckedAt ?? m.updatedAt,
354	      },
355	    ];
356	  });
357	}
