205	
206	function formatAgo(ms: number): string {
207	  const minutes = Math.round(ms / 60000);
208	  if (minutes < 1) return "à l'instant";
209	  if (minutes < 60) return `il y a ${minutes} min`;
210	  const hours = Math.round(minutes / 60);
211	  if (hours < 48) return `il y a ${hours} h`;
212	  const days = Math.round(hours / 24);
213	  return `il y a ${days} j`;
214	}
215	
216	export interface HealthCheckResult {
217	  task: ExternalTask;
218	  transitioned: boolean;
219	}
220	
221	/**
222	 * Compute + persist current health for one task, publishing 'task-healthcheck'
223	 * ONLY on a transition (healthy -> unhealthy, or a scheduled job newly going
224	 * late) so the event stream doesn't spam on every steady-state tick. Compares
225	 * against the PREVIOUS persisted `health.healthy` (daemon) / `health.late`
226	 * (scheduled) to detect that transition.
227	 */
228	export async function checkTaskHealth(
229	  slug: string | undefined,
230	  id: string,
231	): Promise<HealthCheckResult | null> {
232	  const task = await resolveTask(slug, id);
233	  if (!task) return null;
234	
235	  const now = new Date();
236	  const nowIso = now.toISOString();
237	  const logMtimeMs = await latestLogMtimeMs(task.logPaths);
238	
239	  if (task.kind === 'daemon') {
240	    const state = await inspect(task.launchdLabel);
241	    const wasHealthy = task.health.healthy;
242	
243	    let healthy: boolean;
244	    let status: ExternalTaskStatus;
245	    let message: string;
246	    let code: NonNullable<ExternalTaskHealth['code']>;
247	    const params: NonNullable<ExternalTaskHealth['params']> = {};
248	
249	    if (!state.loaded) {
250	      healthy = false;
251	      status = 'unhealthy';
252	      message = "job non chargé dans launchd (launchctl print a échoué)";
253	      code = 'daemon_not_loaded';
254	    } else if (state.running && state.pid) {
255	      healthy = true;
256	      status = 'running';
257	      message = `PID ${state.pid} actif`;
258	      code = 'daemon_running';
259	      params.pid = state.pid;
260	    } else if (typeof state.lastExitCode === 'number' && state.lastExitCode !== 0) {
261	      healthy = false;
262	      status = 'failed';
263	      message = `dernier code de sortie ${state.lastExitCode}, non relancé`;
264	      code = 'daemon_exit_code';
265	      params.code = state.lastExitCode;
266	    } else {
267	      healthy = false;
268	      status = 'unhealthy';
269	      message = 'chargé mais aucun PID actif';
270	      code = 'daemon_no_pid';
271	    }
272	
273	    if (logMtimeMs !== undefined) {
274	      const logAgeMs = now.getTime() - logMtimeMs;
275	      message += ` — log ${formatAgo(logAgeMs)}`;
276	      params.logAgeMinutes = Math.max(0, Math.round(logAgeMs / 60_000));
277	    } else if (task.logPaths.length > 0) {
278	      message += ' — aucun fichier de log trouvé';
279	      params.noLogFile = true;
280	    }
281	
282	    const transitioned = wasHealthy !== undefined && wasHealthy !== healthy;
283	
284	    const patched = await patchTask(
285	      task.id,
286	      {
287	        status,
288	        pid: state.pid,
289	        health: { lastCheckedAt: nowIso, healthy, code, params, message },
290	      },
291	      { slug: task.project.slug },
292	    );
293	    const written = patched ?? task;
294	
295	    if (transitioned) {
296	      publish({
297	        type: 'task-healthcheck',
298	        slug: written.project.slug,
299	        id: written.id,
300	        ok: healthy,
301	        message,
302	      });
303	    }
304	
305	    return { task: written, transitioned };
306	  }
307	
308	  // scheduled
309	  const state = await inspect(task.launchdLabel);
310	  const lastRunAtMs = logMtimeMs;
311	  const lastRunAt = lastRunAtMs !== undefined ? new Date(lastRunAtMs).toISOString() : task.lastRunAt;
312	  // launchd only reports a real exit code once the job has exited in the
313	  // CURRENT session; a job that hasn't rerun since the last login prints
314	  // "last exit code = (never exited)" -> unparsed -> undefined here. An UNKNOWN
315	  // exit must be treated as "not a known failure", NEVER as a failure —
316	  // otherwise a perfectly healthy job that simply hasn't fired yet shows a
317	  // false "dégradé" (exactly the false alarm this dashboard must avoid).
318	  // Prefer a real exit code parsed from run-boundary markers (see module doc
319	  // on `markerExitCode`) over launchd's session-scoped register.
320	  const markerExit = await markerExitCode(task.logPaths);
321	  const knownExit = markerExit ?? state.lastExitCode ?? task.lastRunExitCode ?? null;
322	  const failedRun = knownExit !== null && knownExit !== 0;
323	  const lastRunSuccess = knownExit === null ? undefined : knownExit === 0;
324	
325	  const wasLate = task.health.late;
326	  let late = false;
327	  if (task.expectedIntervalHours !== undefined && lastRunAtMs !== undefined) {
328	    const maxGapMs = task.expectedIntervalHours * 1.25 * 60 * 60 * 1000;
329	    late = now.getTime() - lastRunAtMs > maxGapMs;
330	  }
331	
332	  let message: string;
333	  const healthParams: NonNullable<ExternalTaskHealth['params']> = {
334	    failed: failedRun,
335	    late,
336	  };
337	  let healthCode: NonNullable<ExternalTaskHealth['code']>;
338	  if (lastRunAtMs !== undefined) {
339	    const lastRunAgeMs = now.getTime() - lastRunAtMs;
340	    healthCode = 'scheduled_last_run';
341	    healthParams.ageMinutes = Math.max(0, Math.round(lastRunAgeMs / 60_000));
342	    if (knownExit !== null) healthParams.exitCode = knownExit;
343	    message = `dernier run ${formatAgo(lastRunAgeMs)}${
344	      failedRun ? ` (échec, code ${knownExit})` : ''
345	    }`;
346	  } else {
347	    healthCode = 'scheduled_no_run';
348	    message = 'aucun run observé';
349	  }
350	  if (late) message += ' — EN RETARD';
351	
352	  const healthy = !late && !failedRun;
353	  // A run that FAILS while staying on schedule must surface live too: with
354	  // marker-derived exit codes (taskLogs.ts) failedRun now flips reliably, so
355	  // gate the SSE event on the healthy transition as well, not just lateness.
356	  const transitioned =
357	    (wasLate !== undefined && wasLate !== late) || task.health.healthy !== healthy;
358	
359	  const patched = await patchTask(
360	    task.id,
361	    {
362	      lastRunAt,
363	      lastRunSuccess,
364	      lastRunExitCode: knownExit,
365	      health: {
366	        lastCheckedAt: nowIso,
367	        healthy,
368	        late,
369	        code: healthCode,
370	        params: healthParams,
371	        message,
372	      },
373	    },
374	    { slug: task.project.slug },
375	  );
376	  const written = patched ?? task;
377	
378	  if (transitioned) {
379	    publish({
380	      type: 'task-healthcheck',
381	      slug: written.project.slug,
382	      id: written.id,
383	      ok: !late,
384	      message,
385	    });
386	  }
387	
388	  return { task: written, transitioned };
389	}
390	
