1	/**
2	 * reminderStore — thin read layer over the evergreen `_reminders/rappels`
3	 * conversation (see `server/cli/remind.ts` for the write path/CLI doctrine).
4	 *
5	 * SINGLE SOURCE OF TRUTH for "what are the pending reminders" so `remind list`
6	 * and the `triage scan` CLI share one predicate instead of two copies drifting
7	 * apart. A reminder IS a conversation item (`kind: 'reminder'`) — this module
8	 * adds no new storage, it only reads the same store `saveConversation`/
9	 * `getConversation` already serve.
10	 */
11	import { ITEM_KIND_LABELS, type Conversation, type ItemPriority, type ReminderItem } from '../../src/types/conversation';
12	import { root } from '../config';
13	import { getConversation, saveConversation, saveFailureReason } from './conversationStore';
14	import { resolveAgentOrigin, readGitBranch, createdByFromOrigin, mergeOrigin } from '../lib/agentOrigin';
15	import type { AgentOrigin, OriginSource } from '../../src/types/agentOrigin';
16	import { isReminderEditOnlyFlip, isReminderOriginOnlyFlip } from './identityGuard';
17	
18	export const REMINDERS_SLUG = '_reminders';
19	export const REMINDERS_ID = 'rappels';
20	
21	/** Reads the evergreen reminders conversation, or `null` if it doesn't exist yet. */
22	export async function getRemindersConversation(): Promise<Conversation | null> {
23	  return getConversation(REMINDERS_SLUG, REMINDERS_ID);
24	}
25	
26	/**
27	 * Loads the evergreen `_reminders` conversation, or builds its skeleton when it
28	 * doesn't exist yet — SHARED by every writer of a reminder (`remind add` CLI,
29	 * the `remind_add` MCP tool), so the evergreen conversation's shape is defined
30	 * in exactly one place rather than copy-pasted per caller.
31	 *
32	 * `source` (D2/D3, chantier « provenance de session », lot 2) lets each
33	 * caller identify itself for the origin resolver — the `remind add` CLI
34	 * defaults to `'cli'`, the `remind_add` MCP tool passes `'mcp'`. Only used on
35	 * the very FIRST call (the skeleton branch); once the conversation exists on
36	 * disk, its origin was already stamped at creation time and this is a no-op.
37	 */
38	export async function loadOrInitRemindersConversation(
39	  source: OriginSource = 'cli',
40	): Promise<Conversation> {
41	  const existing = await getRemindersConversation();
42	  if (existing) return existing;
43	
44	  const now = new Date().toISOString();
45	  const origin = resolveAgentOrigin({
46	    env: process.env,
47	    cwd: root(),
48	    source,
49	    git: readGitBranch,
50	    now,
51	  });
52	  return {
53	    schemaVersion: 1,
54	    id: REMINDERS_ID,
55	    project: {
56	      slug: REMINDERS_SLUG,
57	      name: 'Rappels',
58	      path: root(),
59	    },
60	    title: 'Rappels',
61	    summary:
62	      "Rappels accumulés au fil du temps, ajoutés depuis n'importe quel projet via `bun run remind add` ou l'outil MCP `remind_add`.",
63	    status: 'pending',
64	    items: [],
65	    createdAt: now,
66	    updatedAt: now,
67	    origin,
68	    createdBy: createdByFromOrigin(origin, undefined),
69	  };
70	}
