72	/**
73	 * Deterministic-enough id for a fresh reminder item — SHARED by every writer
74	 * (see `loadOrInitRemindersConversation`), so the id shape lives in one place.
75	 */
76	export function newReminderItemId(): string {
77	  return `reminder-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
78	}
79	
80	/**
81	 * Build a fresh `ReminderItem` — SHARED by every writer that creates a
82	 * reminder (`remind add` CLI, the `remind_add` MCP tool) so the item's shape
83	 * (id, kind, title, prompt/body, context, `origin`) lives in exactly ONE
84	 * place rather than two independently-maintained copies (chantier
85	 * « provenance de session », lot 7 — the two call sites used to build this
86	 * object inline, byte-for-byte identically except for `origin`, which
87	 * neither of them stamped at all before this lot).
88	 *
89	 * `origin` is REQUIRED (not optional/defaulted here): every caller already
90	 * has a resolved `AgentOrigin` in hand (`resolveAgentOrigin({..., source:
91	 * 'cli' | 'mcp'})`) by the time it calls this — this function never resolves
92	 * one itself, so it stays a pure, trivially-testable builder.
93	 */
94	export function buildReminderItem(
95	  input: { text: string; dueAt?: string; priority?: ItemPriority; project?: string; context?: string },
96	  origin: AgentOrigin,
97	): ReminderItem {
98	  const text = input.text.trim();
99	  return {
100	    id: newReminderItemId(),
101	    kind: 'reminder',
102	    title: ITEM_KIND_LABELS.reminder,
103	    prompt: text,
104	    context: input.context ?? (input.project ? `Ajouté depuis le projet « ${input.project} ».` : undefined),
105	    body: text,
106	    status: 'pending',
107	    origin,
108	    ...(input.priority ? { priority: input.priority } : {}),
109	    ...(input.dueAt ? { dueAt: new Date(input.dueAt).toISOString() } : {}),
110	  };
111	}
