123	/** Every `reminder` item regardless of status (`pending` AND `answered`). */
124	export async function listAllReminders(): Promise<ReminderItem[]> {
125	  const conversation = await getRemindersConversation();
126	  return conversation?.items.filter((item): item is ReminderItem => item.kind === 'reminder') ?? [];
