129	/**
130	 * SINGLE definition of "en retard" (pending + `dueAt` present + parseable +
131	 * in the past) — shared by `hubPulse.ts`'s reminders widget AND
132	 * `speakerService.ts`'s overdue-announcement tick, so the two never drift
133	 * into two copies of the same predicate (same discipline this module's own
134	 * header claims for "what are the pending reminders"). Pure — no I/O, safe
135	 * to import from a pure-math module like `hubPulse.ts`'s `computePulse`.
136	 */
137	export function isReminderOverdue(item: { status: string; dueAt?: string }, now: number): boolean {
138	  if (item.status !== 'pending' || !item.dueAt) return false;
139	  const due = Date.parse(item.dueAt);
140	  return !Number.isNaN(due) && due < now;
