143	/**
144	 * Locates a reminder BY ID across the whole `_reminders` conversation —
145	 * `pending` OR `answered` — so `remind read <id>` and `remind done <id>` can
146	 * both find an item regardless of where it sits in its lifecycle. Returns the
147	 * parent conversation alongside the item so a caller (e.g. `remind done`) can
148	 * build the next conversation body without a second read (and therefore
149	 * without racing the on-disk file between the two reads).
150	 */
151	export async function findReminderById(
152	  id: string,
153	): Promise<{ conversation: Conversation; item: ReminderItem } | null> {
154	  const conversation = await getRemindersConversation();
155	  if (!conversation) return null;
156	  const item = conversation.items.find(
157	    (it): it is ReminderItem => it.kind === 'reminder' && it.id === id,
158	  );
159	  if (!item) return null;
160	  return { conversation, item };
161	}
