163	/* -------------------------------------------------------------------------- */
164	/*  Origin stamping (D4, chantier « provenance de session », lot 7)           */
165	/* -------------------------------------------------------------------------- */
166	
167	export type StampReminderOriginResult =
168	  | { kind: 'not-found' }
169	  | { kind: 'unchanged'; item: ReminderItem }
170	  | { kind: 'stamped'; item: ReminderItem }
171	  | { kind: 'error'; error: unknown };
172	
173	/**
174	 * Upgrade ONE reminder item's `origin` via `mergeOrigin` (the higher-
175	 * `capturedBy`-ranked of the on-disk origin and `incomingOrigin` wins —
176	 * `server/lib/agentOrigin.ts`) — the item-level counterpart of
177	 * `stampConversationOrigin`/`stampChipOrigin` for a record that is an ITEM
178	 * of the evergreen `_reminders` conversation rather than a document of its
179	 * own. `items[].response`/`status` are NEVER touched: the delta built here
180	 * is verified by `isReminderOriginOnlyFlip` (the identity guard's narrow,
181	 * origin-only counterpart to `isReminderDoneOnlyFlip`) BEFORE the write —
182	 * the SAME defense-in-depth discipline `remind done` already applies to its
183	 * own narrower delta.
184	 *
185	 * No-op (kind: 'unchanged', nothing written) when the merge produces the
186	 * exact origin already on disk — a replayed/late hook invocation, or a
187	 * `backfill-origin` re-run, is therefore always safe to re-run.
188	 */
189	export async function stampReminderOrigin(
190	  itemId: string,
191	  incomingOrigin: AgentOrigin,
192	): Promise<StampReminderOriginResult> {
193	  const found = await findReminderById(itemId);
194	  if (!found) return { kind: 'not-found' };
195	  const { conversation, item } = found;
196	
197	  const merged = mergeOrigin(item.origin, incomingOrigin);
198	  if (JSON.stringify(merged) === JSON.stringify(item.origin)) {
199	    return { kind: 'unchanged', item };
200	  }
201	
202	  const nextItem: ReminderItem = { ...item, origin: merged };
203	  const nextItems = conversation.items.map((it) => (it.id === itemId ? nextItem : it));
204	  // Echo the on-disk updatedAt so the store's optimistic lock accepts the
205	  // write — same convention as `stampConversationOrigin`/`remind done`.
206	  const nextConversation: Conversation = { ...conversation, items: nextItems };
207	
208	  if (!isReminderOriginOnlyFlip(conversation, nextConversation)) {
209	    return {
210	      kind: 'error',
211	      error:
212	        'identity guard: le delta construit pour stamp-origin ne correspond pas exactement au ' +
213	        "flip autorisé (origin d'un seul item kind:'reminder' changé, rien d'autre) — écriture refusée.",
214	    };
215	  }
216	
217	  const result = await saveConversation(REMINDERS_SLUG, REMINDERS_ID, nextConversation);
218	  if (!result.ok) return { kind: 'error', error: saveFailureReason(result) };
219	
220	  const written = result.conversation.items.find(
221	    (it): it is ReminderItem => it.kind === 'reminder' && it.id === itemId,
222	  );
223	  return { kind: 'stamped', item: written ?? nextItem };
224	}
225	
226	/* -------------------------------------------------------------------------- */
227	/*  Edit (remind update, MCP remind_update)                                   */
228	/* -------------------------------------------------------------------------- */
229	
230	/**
231	 * An edit to ONE reminder. Every field is optional; `dueAt: null` clears the
232	 * due date. `status: 'done'` is the same flip as `remind done`, `'pending'`
233	 * reopens a done reminder.
234	 */
235	export interface ReminderPatch {
236	  text?: string;
237	  dueAt?: string | null;
238	  priority?: ItemPriority;
239	  status?: 'pending' | 'done';
240	}
241	
242	/**
243	 * Pure: the item after `patch`. Text rewrites `body` and `prompt` together
244	 * (the convention of `buildReminderItem`); a done reminder that stays done
245	 * keeps its original `answeredAt`.
246	 */
247	export function applyReminderPatch(item: ReminderItem, patch: ReminderPatch, now: string): ReminderItem {
248	  const next: ReminderItem = { ...item };
249	  if (patch.text !== undefined) {
250	    const text = patch.text.trim();
251	    next.body = text;
252	    next.prompt = text;
253	  }
254	  if (patch.dueAt === null) delete next.dueAt;
255	  else if (patch.dueAt !== undefined) next.dueAt = new Date(patch.dueAt).toISOString();
256	  if (patch.priority !== undefined) next.priority = patch.priority;
257	  if (patch.status === 'done' && item.status !== 'answered') {
258	    next.status = 'answered';
259	    next.response = { done: true };
260	    next.answeredAt = now;
261	  } else if (patch.status === 'pending') {
262	    next.status = 'pending';
263	    delete next.response;
264	    delete next.answeredAt;
265	  }
266	  return next;
267	}
268	
269	/** Validation shared by the CLI and the MCP tool; returns an error message or null. */
270	export function reminderPatchError(patch: ReminderPatch): string | null {
271	  if (patch.text !== undefined && !patch.text.trim()) return 'le texte ne peut pas être vide';
272	  if (typeof patch.dueAt === 'string' && Number.isNaN(Date.parse(patch.dueAt))) {
273	    return `échéance invalide (date ISO attendue) : "${patch.dueAt}"`;
274	  }
275	  if (
276	    patch.text === undefined &&
277	    patch.dueAt === undefined &&
278	    patch.priority === undefined &&
279	    patch.status === undefined
280	  ) {
281	    return 'rien à modifier (texte, échéance, priorité ou statut attendu)';
282	  }
283	  return null;
284	}
285	
286	export type UpdateReminderResult =
287	  | { kind: 'not-found' }
288	  | { kind: 'invalid'; error: string }
289	  | { kind: 'unchanged'; item: ReminderItem }
290	  | { kind: 'updated'; item: ReminderItem }
291	  | { kind: 'error'; error: string };
292	
293	const UPDATE_MAX_ATTEMPTS = 3;
294	
295	/**
296	 * Edit ONE reminder — the single write path of `remind update` and the MCP
297	 * `remind_update` tool. The delta is re-checked by `isReminderEditOnlyFlip`
298	 * before the write (only that item, only editable fields, status limited to
299	 * the exact done/reopen shapes), then saved with the same bounded retry on
300	 * an optimistic-lock conflict as `remind_add`: each attempt re-reads the
301	 * evergreen conversation and re-applies the patch onto the fresh copy.
302	 */
303	export async function updateReminder(itemId: string, patch: ReminderPatch): Promise<UpdateReminderResult> {
304	  const invalid = reminderPatchError(patch);
305	  if (invalid) return { kind: 'invalid', error: invalid };
306	
307	  let lastConflict = 'raison inconnue';
