/**
 * Remote MCP surface — Lot 3 du chantier « MCP distant / connecteur claude.ai ».
 *
 * Builds a FRESH `McpServer` per HTTP request, exposing a HARD WHITELIST of
 * exactly 13 of the 34 first-party tools (see `REMOTE_TOOL_NAMES` below) —
 * never the full bus. Two invariants matter here:
 *
 *   1. NARROW SURFACE: only `registerBrainTools`/`registerHubWriteTools`/
 *      `registerHubReadTools` are called, each filtered to `REMOTE_TOOL_NAMES`
 *      via their `allow` option (lots 1-3). `registerHtmlReviewTools` is NEVER
 *      called (Galley review tools stay local-only), and NEITHER
 *      `registerBrainResources` NOR `registerBrainPrompts` is ever called —
 *      resources/prompts don't pass through the `BrainToolRegistrar` chokepoint
 *      (zod I/O validation, access control, rate-limit, timeout, sanitization,
 *      audit), so they must never reach an untrusted transport.
 *
 *   2. SHARED REGISTRAR, FRESH SERVER: `sharedRegistrar` is constructed ONCE at
 *      module load and reused across every `createRemoteServer()` call — this
 *      is what makes the rate-limiter and the audit trail SURVIVE across HTTP
 *      requests (each request gets its own `McpServer`/transport, but they all
 *      register onto the SAME `BrainToolRegistrar`, hence the SAME
 *      process-local `RateLimiter` buckets). `middleware.ts`'s `register()` is
 *      idempotent on `registered` for exactly this reason: without it, calling
 *      `createRemoteServer()` on every HTTP request would grow `registered`
 *      unboundedly on a 24/7 process.
 *
 * Authentication is OUT OF SCOPE here — this module itself stays
 * authentication-free by design. Identity is gated one layer up:
 * `server/routes/mcpRemote.ts`'s `mountMcpRemote()` mounts
 * `server/middleware/mcpAuth.ts`'s `mcpAuthMiddleware` IN FRONT of `/mcp`
 * (lot 4), so no request reaches this module's handlers unauthenticated.
 */
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';

import { BrainToolRegistrar } from './middleware';
import { redactLocalPathsInText } from './remoteRedaction';
import { registerBrainTools } from './brainTools';
import { registerHubWriteTools } from './hubWriteTools';
import { registerHubReadTools } from './hubReadTools';

/**
 * The EXACT 13-tool whitelist exposed on the remote HTTP surface. Any tool
 * name NOT in this set (including every `html_review_*` tool, and the P5
 * migration-engine / capture-gate tools) is never registered on a remote
 * server, regardless of what `registerBrainTools`/`registerHub*Tools` would
 * otherwise expose on the full stdio bus.
 */
export const REMOTE_TOOL_NAMES: ReadonlySet<string> = new Set([
  'memory_search',
  'project_state_get',
  'lessons_list_validated',
  'chips_list',
  'chip_read',
  'convo_list',
  'convo_read',
  'remind_list',
  'git_status',
  'chip_create',
  'convo_create',
  'remind_add',
  'remind_update',
]);

/**
 * ONE registrar, shared across every `createRemoteServer()` call for the
 * lifetime of this process — see file header point 2. Process-local (in
 * memory), exactly like the stdio bus's per-process registrars.
 *
 * KNOWN LIMITATION (reviewed 2026-08-29, not fixed — see reasoning below):
 * the underlying `RateLimiter` buckets a tool's rate limit by TOOL NAME only
 * (`server/mcp/rateLimit.ts`), not by caller identity — so two callers
 * hitting the same tool share one budget. Today `MCP_ALLOWED_EMAILS` lists
 * exactly one identity, so the only real effect is Franck being able to
 * throttle himself across two of his own devices (bounded to one bucket's
 * refill time, e.g. ~20s for a write tool) — not a cross-identity DoS, since
 * `mcpAuthMiddleware` already requires a valid token AND allowlist membership
 * before any request reaches this registrar. If `MCP_ALLOWED_EMAILS` ever
 * grows past one identity, key the bucket by `${tool}:${email}` instead
 * (thread `req.mcpAuth.email` from `mcpAuth.ts` through `createRemoteServer()`
 * into `BrainToolRegistrar.register()`) — open a chip when that happens
 * rather than pre-building it for a scenario that doesn't exist yet.
 */
// `errorFilter`: a thrown store/fs error (`EEXIST … mkdir '/var/…'`) must not
// carry a local path to the remote caller either (remoteRedaction.ts).
const sharedRegistrar = new BrainToolRegistrar(undefined, { errorFilter: redactLocalPathsInText });

/**
 * Build a fresh `McpServer` exposing exactly `REMOTE_TOOL_NAMES`, registered
 * through the SAME shared registrar (rate-limit/audit persist across calls).
 * Call this ONCE PER HTTP REQUEST — never cache the returned server across
 * requests (stateless transport, see `server/routes/mcpRemote.ts`).
 */
export function createRemoteServer(): McpServer {
  const server = new McpServer({ name: 'workstation-bus-remote', version: '1.0.0' });
  // `redactLocalPaths` on all three families (chip
  // 2026-09-25-redact-project-path-in-remote-convo-read): no remote result —
  // read OR write — reveals a local filesystem path (remoteRedaction.ts).
  registerBrainTools(server, { registrar: sharedRegistrar, allow: REMOTE_TOOL_NAMES, redactLocalPaths: true });
  registerHubWriteTools(server, {
    registrar: sharedRegistrar,
    allow: REMOTE_TOOL_NAMES,
    // D2 (chantier « provenance de session », lot 2; P1 fix, revue
    // adversariale, widened to ALL THREE hub-write tools): every
    // chip/conversation/reminder `chip_create`/`convo_create`/`remind_add`
    // writes through THIS remote mount is stamped `runtime: 'claude-ai'` —
    // the local process's own Claude Code session env vars (if any) belong
    // to the SERVER, never to the remote caller (identified upstream by
    // `mcpAuthMiddleware`, out of scope here), so trusting them would
    // misattribute authorship to whichever session happens to be running
    // the workstation server. `hubWriteTools.ts`'s
    // `RegisterHubWriteToolsOptions.originOverride` doc carries the full
    // invariant, repeated at each of the three handlers themselves.
    originOverride: { runtime: 'claude-ai', source: 'mcp', capturedBy: 'explicit' },
    redactLocalPaths: true,
  });
  registerHubReadTools(server, {
    registrar: sharedRegistrar,
    allow: REMOTE_TOOL_NAMES,
    // Constat 4 (revue adversariale, chantier « provenance de session »):
    // `convo_read`'s full `AgentOrigin` (cwd/repoRoot/branch/hostSessionId/
    // entrypoint) describes a LOCAL session's filesystem — never something a
    // remote claude.ai caller should learn. `hubReadTools.ts`'s
    // `RegisterHubReadToolsOptions.redactLocalPaths` doc carries the full
    // rationale.
    redactLocalPaths: true,
  });
  // Deliberately NEVER called on the remote surface:
  //   - registerHtmlReviewTools (Galley stays local-only)
  //   - registerBrainResources / registerBrainPrompts (bypass the chokepoint)
  return server;
}

/** Test/inspection helper: the shared registrar's live `registered` list. */
export function remoteRegisteredToolNames(): readonly string[] {
  return sharedRegistrar.registered;
}

