/** Ids d'items déjà vus — persistés pour ne pas re-notifier entre sessions. */
const SEEN_KEY = 'seen-notification-ids';
const SEEN_LIMIT = 500;
const DEBOUNCE_MS = 800;

function loadSeenIds(): Set<string> {
  try {
    const raw = window.localStorage.getItem(SEEN_KEY);
    if (!raw) return new Set();
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return new Set();
    return new Set(parsed.filter((value): value is string => typeof value === 'string'));
  } catch {
    return new Set();
  }
}

/** Persiste le Set en bornant sa taille (les plus récents sont conservés). */
function persistSeenIds(seen: Set<string>): Set<string> {
  const bounded = [...seen].slice(-SEEN_LIMIT);
  try {
    window.localStorage.setItem(SEEN_KEY, JSON.stringify(bounded));
  } catch {
    /* localStorage indisponible */
  }
  return new Set(bounded);
}

